"""SparkX autonomy stack (LOCKED - teams do not edit this file).

Starts the fixed infrastructure and the team's three nodes:

    robot_localization/ekf_node          wheel odometry + IMU  -> odom -> base_link
    pointcloud_to_laserscan              /lidar/points         -> /scan
    slam_toolbox                         /scan                 -> /map, map -> odom
    Nav2 (controller, planner, behaviors, bt_navigator)        -> /cmd_vel
    sparkx_baseline/nav_guard            repairs a navigation start-up that stalls
    sparkx_team/perception               (team file 1: perception.py)
    sparkx_team/memory                   (team file 2: memory.py)
    sparkx_team/mission                  (team file 3: mission.py)

Every node reads its parameters from the team's `config/team.yaml` (team file 4). Two things are
forced here and cannot be changed from that file: `use_sim_time` and the topic wiring.

  ros2 launch sparkx_baseline baseline.launch.py [use_yolo:=false] [mission:=true] [team_config:=/path/team.yaml]
"""
import os

from ament_index_python.packages import get_package_share_directory
from launch import LaunchDescription
from launch.actions import DeclareLaunchArgument, TimerAction
from launch.conditions import IfCondition
from launch.substitutions import LaunchConfiguration as L
from launch_ros.actions import Node


def generate_launch_description():
    team_share = get_package_share_directory('sparkx_team')
    cfg = L('team_config')
    st = {'use_sim_time': True}
    nav_nodes = [('nav2_controller', 'controller_server'), ('nav2_planner', 'planner_server'),
                 ('nav2_behaviors', 'behavior_server'), ('nav2_bt_navigator', 'bt_navigator')]
    return LaunchDescription([
        DeclareLaunchArgument('use_yolo', default_value='false'),
        DeclareLaunchArgument('mission', default_value='true'),
        DeclareLaunchArgument('team_config', default_value=os.path.join(team_share, 'config', 'team.yaml')),
        Node(package='robot_localization', executable='ekf_node', name='ekf_filter_node', output='log',
             parameters=[cfg, st]),
        Node(package='pointcloud_to_laserscan', executable='pointcloud_to_laserscan_node',
             name='pointcloud_to_laserscan', output='log', parameters=[cfg, st],
             remappings=[('cloud_in', '/lidar/points'), ('scan', '/scan')]),
        Node(package='slam_toolbox', executable='async_slam_toolbox_node', name='slam_toolbox', output='log',
             parameters=[cfg, {**st, 'use_lifecycle_manager': True}]),
        # Each lifecycle manager starts a few seconds after the servers it manages: a manager that
        # calls a server the instant its service appears can lose the reply and then waits for ever
        # (see nav_guard.py, which also repairs a start-up that stalls all the same).
        TimerAction(period=3.0, actions=[
            Node(package='nav2_lifecycle_manager', executable='lifecycle_manager', name='lifecycle_manager_slam',
                 output='log', parameters=[{**st, 'autostart': True, 'node_names': ['slam_toolbox'],
                                            'bond_timeout': 0.0}]),
        ]),
        TimerAction(period=5.0, actions=[
            *[Node(package=p, executable=e, name=e, output='log', parameters=[cfg, st],
                   remappings=[('cmd_vel', '/cmd_vel')]) for p, e in nav_nodes],
            Node(package='sparkx_baseline', executable='nav_guard', output='screen',
                 parameters=[{'nodes': ['slam_toolbox'] + [e for _, e in nav_nodes]}]),
        ]),
        TimerAction(period=9.0, actions=[
            Node(package='nav2_lifecycle_manager', executable='lifecycle_manager', name='lifecycle_manager_navigation',
                 output='log', parameters=[{**st, 'autostart': True, 'node_names': [e for _, e in nav_nodes]}]),
        ]),
        Node(package='sparkx_team', executable='perception', output='screen',
             parameters=[cfg, {**st, 'use_yolo': L('use_yolo'), 'model_dir': os.path.join(team_share, 'models')}]),
        Node(package='sparkx_team', executable='memory', output='screen', parameters=[cfg, st]),
        Node(package='sparkx_team', executable='mission', output='screen', parameters=[cfg, st],
             condition=IfCondition(L('mission'))),
    ])
